    {
      "@type": "FAQPage",
      "@id": "https://www.data4thepeople.com/p/ppi-scuba-diver#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is the PPI Scuba Diver?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "An animated chart of every item in the Producer Price Index for final demand. The diver sits as deep as the 12-month change. Items that added to it hang below as anchors, and items that took away from it float above. It covers every month from October 2016 to September 2026."
          }
        },
        {
          "@type": "Question",
          "name": "What is PPI final demand?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The Producer Price Index for final demand measures the prices U.S. businesses receive for goods, services and construction sold to final buyers: households, businesses buying equipment, governments and buyers overseas. BLS publishes it each month as series WPUFD4."
          }
        },
        {
          "@type": "Question",
          "name": "How is the PPI different from the CPI?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The CPI measures prices consumers pay. The PPI measures prices businesses receive, including wholesalers' and retailers' margins and sales to businesses, governments and buyers overseas. Our CPI Hot Air Balloon shows the CPI the same way."
          }
        },
        {
          "@type": "Question",
          "name": "What is driving PPI right now?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In September 2026, PPI final demand was 6.3% higher than a year earlier. Gasoline added the most, 0.76 points, with a price 66.1% higher than a year earlier. Fuel retailing margins took away the most, 0.12 points."
          }
        },
        {
          "@type": "Question",
          "name": "Why do some months miss your tie-out test?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Before July 2021, BLS published its indexes rounded to one decimal place, which can move a 12-month change by up to about 0.09 points. More items also had no published index then. Every month from July 2022 on passes. We show the earlier months and flag them."
          }
        },
        {
          "@type": "Question",
          "name": "What does the gray circle mean?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It is the part of BLS's published change that our items do not add up to. With it, the bubbles add up to BLS's figure exactly. It is small from July 2022 on."
          }
        },
        {
          "@type": "Question",
          "name": "What does a dashed ring mean?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "BLS does not publish an index for that item in those months. We used the price change of the category above it, so its color is an estimate."
          }
        },
        {
          "@type": "Question",
          "name": "Why does the chart show \"margins\"?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Final demand includes the services that wholesalers and retailers provide, measured by their margins: what they sell an item for, less what they paid for it. When margins shrink, they pull the PPI down even if the goods themselves cost more."
          }
        },
        {
          "@type": "Question",
          "name": "Is the data seasonally adjusted?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. We use the data that is not seasonally adjusted, the same data BLS uses to move its weights forward from one December to the next."
          }
        },
        {
          "@type": "Question",
          "name": "How often is the chart updated?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Each month, after BLS releases the PPI."
          }
        },
        {
          "@type": "Question",
          "name": "Can I embed the chart?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. It is free to use and embed. Add #embed=1 to the end of the full visualization's address for the 780-pixel version shown on this page."
          }
        },
        {
          "@type": "Question",
          "name": "Where does the data come from?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The U.S. Bureau of Labor Statistics: monthly PPI index values for final demand and every commodity in it, and the relative importance tables that give each commodity's share of final demand."
          }
        }
      ]
